:root {
  --purple: #b44cff;
  --purple-soft: #d9a6ff;
  --cyan: #43f6ff;
  --pink: #ff4fa3;
  --gold: #ffd166;
  --ink: #08020f;
  --glass: rgba(18, 6, 36, 0.55);
  --line: rgba(180, 76, 255, 0.35);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: #f4eaff;
  font-family: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  touch-action: none;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: radial-gradient(120% 90% at 50% 0%, #1a0733 0%, #0b0319 48%, #04010a 100%);
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(130% 100% at 50% 46%, transparent 40%, rgba(2, 0, 8, 0.55) 100%),
    linear-gradient(180deg, rgba(3, 0, 9, 0.45) 0%, transparent 18%, transparent 78%, rgba(3, 0, 9, 0.7) 100%);
  z-index: 2;
}

#flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 6;
  opacity: 0;
  background: radial-gradient(circle at 62% 22%, rgba(233, 200, 255, 0.95), rgba(150, 60, 255, 0.5) 42%, transparent 72%);
  transition: opacity 180ms ease-out;
}
#flash.on { opacity: 0.9; transition: none; }

/* ---------- HUD ---------- */
#hud {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.35s ease;
}
#hud.hidden { opacity: 0; pointer-events: none; }
#hud button { pointer-events: auto; }

.topbar {
  position: absolute;
  top: calc(10px + var(--safe-t));
  left: calc(14px + var(--safe-l));
  right: calc(14px + var(--safe-r));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.score-panel {
  display: flex;
  flex-direction: column;
  line-height: 1;
  padding: 8px 14px 9px;
  border-radius: 12px;
  background: linear-gradient(160deg, rgba(24, 8, 46, 0.72), rgba(9, 3, 20, 0.5));
  border: 1px solid rgba(180, 76, 255, 0.28);
  box-shadow: 0 0 24px rgba(120, 40, 220, 0.18), inset 0 0 20px rgba(120, 40, 220, 0.1);
  backdrop-filter: blur(6px);
}
.score-panel .label {
  font-size: 9px;
  letter-spacing: 0.28em;
  color: #b79ad6;
  margin-bottom: 4px;
}
#score {
  font-family: ui-monospace, "Courier New", monospace;
  font-weight: 700;
  font-size: clamp(22px, 3.4vw, 30px);
  letter-spacing: 0.04em;
  color: #fff;
  text-shadow: 0 0 12px rgba(180, 76, 255, 0.9), 0 0 30px rgba(67, 246, 255, 0.3);
}
.score-panel .best {
  margin-top: 5px;
  font-size: 9px;
  letter-spacing: 0.18em;
  color: #7f6b9a;
}
.score-panel .best b { color: var(--purple-soft); font-weight: 600; }

.hearts {
  display: flex;
  gap: 7px;
  padding-top: 8px;
  filter: drop-shadow(0 0 8px rgba(255, 79, 163, 0.7));
}
.heart {
  font-size: clamp(18px, 3vw, 24px);
  line-height: 1;
  color: var(--pink);
  text-shadow: 0 0 10px rgba(255, 79, 163, 0.9);
  transition: transform 0.25s ease, color 0.25s ease, opacity 0.25s ease;
}
.heart.empty { color: rgba(120, 90, 150, 0.28); text-shadow: none; transform: scale(0.82); }
.heart.pop { transform: scale(1.35); }

.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  border: 1px solid rgba(180, 76, 255, 0.3);
  background: rgba(16, 6, 32, 0.62);
  color: var(--purple-soft);
  font-size: 17px;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: transform 0.15s ease, border-color 0.2s ease, color 0.2s ease;
}
.icon-btn:active { transform: scale(0.92); }
.icon-btn.muted { color: #6e5c84; border-color: rgba(120, 90, 150, 0.25); }

.combo {
  position: absolute;
  top: calc(88px + var(--safe-t));
  right: calc(18px + var(--safe-r));
  font-family: ui-monospace, "Courier New", monospace;
  font-weight: 700;
  font-size: clamp(20px, 3.6vw, 34px);
  letter-spacing: 0.02em;
  color: var(--gold);
  text-shadow: 0 0 14px rgba(255, 209, 102, 0.8), 0 0 34px rgba(255, 130, 40, 0.4);
  opacity: 0;
  transform: translateY(6px) scale(0.85);
  transition: opacity 0.18s ease, transform 0.18s ease;
}
.combo.show { opacity: 1; transform: translateY(0) scale(1); }
.combo.pulse { animation: comboPulse 0.28s ease-out; }
@keyframes comboPulse {
  0% { transform: scale(1); }
  40% { transform: scale(1.24) rotate(-2deg); }
  100% { transform: scale(1); }
}

.banner {
  position: absolute;
  top: calc(22% + var(--safe-t));
  left: 50%;
  transform: translate(-50%, 0) scale(0.9);
  padding: 8px 22px;
  border-radius: 999px;
  border: 1px solid rgba(217, 166, 255, 0.5);
  background: linear-gradient(90deg, rgba(70, 16, 120, 0.35), rgba(140, 60, 255, 0.5), rgba(70, 16, 120, 0.35));
  box-shadow: 0 0 34px rgba(160, 70, 255, 0.5), inset 0 0 22px rgba(255, 255, 255, 0.12);
  font-size: clamp(10px, 1.6vw, 13px);
  font-weight: 700;
  letter-spacing: 0.34em;
  white-space: nowrap;
  color: #fff;
  text-shadow: 0 0 14px rgba(217, 166, 255, 1);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.banner.show { opacity: 1; transform: translate(-50%, 0) scale(1); }
.banner.hot {
  border-color: rgba(255, 209, 102, 0.65);
  box-shadow: 0 0 40px rgba(255, 180, 60, 0.5), inset 0 0 22px rgba(255, 255, 255, 0.2);
  color: #fff4d0;
}

.nova-panel {
  position: absolute;
  left: calc(16px + var(--safe-l));
  bottom: calc(18px + var(--safe-b));
  width: min(42vw, 300px);
  padding: 9px 12px 11px;
  border-radius: 14px;
  background: linear-gradient(150deg, rgba(24, 8, 46, 0.7), rgba(9, 3, 20, 0.46));
  border: 1px solid rgba(180, 76, 255, 0.26);
  backdrop-filter: blur(7px);
  box-shadow: 0 0 26px rgba(110, 40, 200, 0.18);
}
.nova-head {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  letter-spacing: 0.22em;
  color: #b79ad6;
  margin-bottom: 6px;
}
#novaPct { color: var(--purple-soft); font-family: ui-monospace, monospace; }
.nova-bar {
  height: 8px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.6);
}
.nova-bar i {
  display: block;
  height: 100%;
  width: 0%;
  border-radius: 99px;
  background: linear-gradient(90deg, #7a2cff, #c56bff 55%, #43f6ff);
  box-shadow: 0 0 14px rgba(180, 76, 255, 0.9);
  transition: width 0.18s ease-out;
}
.nova-bar.full i { animation: novaGlow 0.8s ease-in-out infinite alternate; }
@keyframes novaGlow {
  from { filter: brightness(1); }
  to { filter: brightness(1.65); }
}
.nova-btn {
  margin-top: 8px;
  width: 100%;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid rgba(180, 76, 255, 0.35);
  background: rgba(60, 20, 110, 0.28);
  color: #8f78ab;
  font: 700 10px/1 "Trebuchet MS", sans-serif;
  letter-spacing: 0.24em;
  cursor: pointer;
  transition: all 0.2s ease;
}
.nova-btn.ready {
  color: #fff;
  border-color: rgba(217, 166, 255, 0.9);
  background: linear-gradient(90deg, rgba(122, 44, 255, 0.85), rgba(196, 107, 255, 0.9));
  box-shadow: 0 0 26px rgba(180, 76, 255, 0.8), inset 0 0 12px rgba(255, 255, 255, 0.3);
  animation: readyPulse 1s ease-in-out infinite alternate;
}
@keyframes readyPulse {
  from { box-shadow: 0 0 16px rgba(180, 76, 255, 0.55), inset 0 0 10px rgba(255, 255, 255, 0.2); }
  to { box-shadow: 0 0 38px rgba(200, 130, 255, 0.95), inset 0 0 16px rgba(255, 255, 255, 0.35); }
}
.nova-btn:active { transform: scale(0.97); }

.jump-btn {
  position: absolute;
  right: calc(20px + var(--safe-r));
  bottom: calc(22px + var(--safe-b));
  width: clamp(78px, 16vw, 104px);
  height: clamp(78px, 16vw, 104px);
  border-radius: 50%;
  border: 2px solid rgba(67, 246, 255, 0.6);
  background: radial-gradient(circle at 35% 28%, rgba(67, 246, 255, 0.34), rgba(12, 30, 48, 0.6) 60%, rgba(6, 6, 20, 0.7));
  color: #d8fdff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  cursor: pointer;
  box-shadow: 0 0 30px rgba(67, 246, 255, 0.35), inset 0 0 22px rgba(67, 246, 255, 0.18);
  transition: transform 0.08s ease, box-shadow 0.15s ease;
  touch-action: none;
}
.jump-btn .arrow { font-size: clamp(20px, 4vw, 26px); line-height: 0.9; text-shadow: 0 0 12px rgba(67, 246, 255, 0.9); }
.jump-btn .txt { font-size: clamp(9px, 1.6vw, 11px); font-weight: 700; letter-spacing: 0.22em; }
.jump-btn:active, .jump-btn.press {
  transform: scale(0.9);
  box-shadow: 0 0 46px rgba(67, 246, 255, 0.7), inset 0 0 30px rgba(67, 246, 255, 0.35);
}

.hintbar {
  position: absolute;
  bottom: calc(10px + var(--safe-b));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 22px;
  font-size: 10px;
  letter-spacing: 0.12em;
  color: rgba(180, 160, 205, 0.5);
  white-space: nowrap;
  pointer-events: none;
}
.hintbar b { color: rgba(217, 166, 255, 0.8); font-weight: 700; }
.hintbar i { font-style: normal; opacity: 0.4; }

/* ---------- Overlays ---------- */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(20px + var(--safe-t)) calc(20px + var(--safe-r)) calc(20px + var(--safe-b)) calc(20px + var(--safe-l));
  background:
    radial-gradient(80% 70% at 50% 38%, rgba(60, 16, 110, 0.42), transparent 65%),
    linear-gradient(180deg, rgba(4, 1, 12, 0.55), rgba(4, 1, 12, 0.86));
  backdrop-filter: blur(3px);
  opacity: 1;
  transition: opacity 0.4s ease, visibility 0.4s ease;
}
.overlay.hidden { opacity: 0; visibility: hidden; pointer-events: none; }

.title-inner {
  position: relative;
  width: min(760px, 100%);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  animation: riseIn 0.8s cubic-bezier(0.2, 0.9, 0.25, 1) both;
}
@keyframes riseIn {
  from { opacity: 0; transform: translateY(22px); }
  to { opacity: 1; transform: translateY(0); }
}

.kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: clamp(8px, 1.5vw, 11px);
  letter-spacing: 0.4em;
  color: #b79ad6;
  text-transform: uppercase;
  margin-bottom: 14px;
}
.kicker i {
  display: inline-block;
  width: clamp(20px, 5vw, 44px);
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--purple));
}
.kicker i:last-child { background: linear-gradient(90deg, var(--purple), transparent); }
.kicker.small { justify-content: center; font-size: 9px; margin-bottom: 8px; color: #a98bc9; }

.logo {
  position: relative;
  margin: 0;
  font-family: "Arial Black", "Trebuchet MS", sans-serif;
  font-weight: 900;
  font-size: clamp(66px, 19vw, 168px);
  line-height: 0.82;
  letter-spacing: 0.06em;
  background: linear-gradient(180deg, #ffffff 0%, #e8c9ff 34%, #b44cff 66%, #6a1fd0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 18px rgba(180, 76, 255, 0.65)) drop-shadow(0 0 54px rgba(120, 40, 255, 0.45));
}
.logo::after {
  content: "";
  position: absolute;
  left: 6%;
  right: 6%;
  bottom: -14px;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(67, 246, 255, 0.9), rgba(180, 76, 255, 0.9), transparent);
  filter: blur(0.4px);
  box-shadow: 0 0 18px rgba(67, 246, 255, 0.7);
}
.logo .sub {
  display: block;
  margin-top: 14px;
  font-family: "Trebuchet MS", sans-serif;
  font-size: clamp(11px, 2.4vw, 17px);
  font-weight: 700;
  letter-spacing: 0.72em;
  padding-left: 0.72em;
  background: none;
  -webkit-text-fill-color: #43f6ff;
  color: #43f6ff;
  text-shadow: 0 0 14px rgba(67, 246, 255, 0.8), 0 0 40px rgba(67, 246, 255, 0.35);
  filter: none;
}

.tagline {
  max-width: 540px;
  margin: clamp(18px, 4vh, 34px) auto 0;
  font-size: clamp(12px, 1.9vw, 15px);
  line-height: 1.65;
  color: #c8b3e0;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.6);
}

.cta {
  position: relative;
  margin-top: clamp(18px, 4vh, 30px);
  padding: 15px 46px;
  border-radius: 999px;
  border: 1px solid rgba(217, 166, 255, 0.85);
  background: linear-gradient(180deg, rgba(180, 76, 255, 0.95), rgba(102, 28, 200, 0.95));
  color: #fff;
  font: 800 clamp(13px, 2vw, 16px)/1 "Trebuchet MS", sans-serif;
  letter-spacing: 0.26em;
  cursor: pointer;
  box-shadow: 0 0 32px rgba(180, 76, 255, 0.55), 0 10px 30px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  transition: transform 0.15s ease, box-shadow 0.2s ease, filter 0.2s ease;
  animation: ctaBreath 2.6s ease-in-out infinite;
}
@keyframes ctaBreath {
  0%, 100% { box-shadow: 0 0 24px rgba(180, 76, 255, 0.45), 0 10px 30px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.4); }
  50% { box-shadow: 0 0 48px rgba(180, 76, 255, 0.8), 0 10px 30px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.5); }
}
.cta:hover { filter: brightness(1.12); transform: translateY(-1px); }
.cta:active { transform: scale(0.96); }

.controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px 26px;
  margin-top: clamp(20px, 4.5vh, 36px);
  font-size: clamp(9px, 1.4vw, 11px);
  letter-spacing: 0.12em;
  color: #8f78ab;
}
.controls b { color: #d9c2f2; font-weight: 700; }

.title-foot {
  position: absolute;
  bottom: calc(14px + var(--safe-b));
  left: 50%;
  transform: translateX(-50%);
  font-size: 8px;
  letter-spacing: 0.34em;
  color: rgba(150, 125, 180, 0.45);
  white-space: nowrap;
}

.panel {
  position: relative;
  width: min(480px, 100%);
  padding: clamp(22px, 5vw, 40px);
  border-radius: 22px;
  text-align: center;
  background: linear-gradient(160deg, rgba(28, 10, 52, 0.92), rgba(9, 3, 20, 0.94));
  border: 1px solid rgba(180, 76, 255, 0.35);
  box-shadow: 0 0 60px rgba(120, 40, 220, 0.28), inset 0 0 40px rgba(120, 40, 220, 0.08);
  animation: riseIn 0.45s cubic-bezier(0.2, 0.9, 0.25, 1) both;
}
.panel h2 {
  margin: 4px 0 18px;
  font-family: "Arial Black", "Trebuchet MS", sans-serif;
  font-size: clamp(28px, 6vw, 46px);
  letter-spacing: 0.08em;
  background: linear-gradient(180deg, #fff, #d9a6ff 55%, #9b3cff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 16px rgba(180, 76, 255, 0.55));
}
.small-panel { width: min(380px, 100%); }

.final-score {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 18px;
}
.final-score span { font-size: 9px; letter-spacing: 0.34em; color: #a98bc9; }
.final-score b {
  font-family: ui-monospace, "Courier New", monospace;
  font-size: clamp(42px, 10vw, 68px);
  line-height: 1;
  color: #fff;
  text-shadow: 0 0 24px rgba(180, 76, 255, 0.8), 0 0 60px rgba(67, 246, 255, 0.25);
}
.final-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 6px;
}
.final-grid > div {
  padding: 9px 6px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(180, 76, 255, 0.16);
}
.final-grid span { display: block; font-size: 8px; letter-spacing: 0.18em; color: #8f78ab; margin-bottom: 3px; }
.final-grid b { font-family: ui-monospace, "Courier New", monospace; font-size: clamp(13px, 2.6vw, 17px); color: #e7d8fa; }
.tiny { margin-top: 16px; font-size: 10px; line-height: 1.6; letter-spacing: 0.1em; color: #7f6b9a; }

/* ---------- Boot ---------- */
#boot {
  z-index: 20;
  background: #08020f;
  transition: opacity 0.6s ease, visibility 0.6s ease;
}
#boot.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.boot-inner { text-align: center; }
.boot-cat { font-size: 34px; filter: drop-shadow(0 0 18px rgba(180, 76, 255, 0.9)); animation: bob 1.1s ease-in-out infinite alternate; }
@keyframes bob { from { transform: translateY(0); } to { transform: translateY(-7px); } }
.boot-text { margin-top: 14px; font-size: 9px; letter-spacing: 0.4em; color: #a98bc9; }
.boot-bar { width: 160px; height: 3px; margin: 12px auto 0; border-radius: 9px; background: rgba(255, 255, 255, 0.08); overflow: hidden; }
.boot-bar i { display: block; width: 40%; height: 100%; background: linear-gradient(90deg, transparent, var(--purple), var(--cyan), transparent); animation: bootSlide 1s ease-in-out infinite; }
@keyframes bootSlide { from { transform: translateX(-120%); } to { transform: translateX(300%); } }

/* ---------- Responsive ---------- */
@media (max-width: 700px) {
  .hintbar { display: none; }
  .nova-panel { width: min(50vw, 240px); padding: 7px 10px 9px; }
  .nova-head { font-size: 8px; }
  .nova-btn { padding: 7px 8px; font-size: 9px; }
  .jump-btn { right: calc(14px + var(--safe-r)); bottom: calc(16px + var(--safe-b)); }
  .title-foot { display: none; }
  .controls { gap: 8px 16px; }
}

@media (max-height: 500px) and (orientation: landscape) {
  .title-inner { transform: scale(0.86); }
  .logo { font-size: clamp(52px, 15vh, 92px); }
