import * as THREE from 'three';

/* TAVI — a neon-purple cat built entirely from primitives. Faces +X, feet at y=0. */
export function createCat() {
  const root = new THREE.Group();
  const rig = new THREE.Group();
  root.add(rig);

  const mats = [];
  const mat = (opts) => {
    const m = new THREE.MeshStandardMaterial(opts);
    mats.push(m);
    return m;
  };

  const fur = mat({
    color: 0x2a1444,
    emissive: 0x6a1fd0,
    emissiveIntensity: 0.42,
    roughness: 0.38,
    metalness: 0.45,
  });
  const furLight = mat({
    color: 0x3b2158,
    emissive: 0x8a3cff,
    emissiveIntensity: 0.28,
    roughness: 0.5,
    metalness: 0.3,
  });
  const neon = mat({
    color: 0x12051f,
    emissive: 0xb44cff,
    emissiveIntensity: 1.9,
    roughness: 0.3,
    metalness: 0.2,
  });
  const cyanMat = mat({
    color: 0x0a2b30,
    emissive: 0x43f6ff,
    emissiveIntensity: 2.2,
    roughness: 0.2,
    metalness: 0.2,
  });
  const pinkMat = mat({
    color: 0x300a1c,
    emissive: 0xff4fa3,
    emissiveIntensity: 1.6,
    roughness: 0.4,
  });

  /* ---------- body ---------- */
  const bodyGroup = new THREE.Group();
  bodyGroup.position.set(0, 1.02, 0);
  rig.add(bodyGroup);

  const torso = new THREE.Mesh(new THREE.SphereGeometry(0.5, 22, 16), fur);
  torso.scale.set(1.14, 0.86, 0.84);
  torso.castShadow = true;
  bodyGroup.add(torso);

  const chest = new THREE.Mesh(new THREE.SphereGeometry(0.32, 16, 12), furLight);
  chest.position.set(0.36, -0.02, 0);
  chest.scale.set(0.9, 0.85, 0.8);
  bodyGroup.add(chest);

  // glowing ribs / fur stripes
  for (let i = 0; i < 3; i++) {
    const stripe = new THREE.Mesh(new THREE.TorusGeometry(0.34 - i * 0.03, 0.022, 6, 18), neon);
    stripe.position.set(-0.18 + i * 0.16, 0.14 - i * 0.02, 0);
    stripe.rotation.y = Math.PI / 2;
    stripe.scale.set(1, 0.9, 0.72);
    bodyGroup.add(stripe);
  }

  /* ---------- head ---------- */
  const headGroup = new THREE.Group();
  headGroup.position.set(0.5, 1.6, 0);
  rig.add(headGroup);

  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.4, 22, 16), fur);
  skull.scale.set(1, 0.94, 0.92);
  headGroup.add(skull);

  const cheeks = new THREE.Mesh(new THREE.SphereGeometry(0.24, 16, 12), furLight);
  cheeks.position.set(0.2, -0.1, 0);
  cheeks.scale.set(0.95, 0.72, 0.92);
  headGroup.add(cheeks);

  const muzzle = new THREE.Mesh(new THREE.SphereGeometry(0.15, 14, 10), furLight);
  muzzle.position.set(0.34, -0.11, 0);
  muzzle.scale.set(0.9, 0.7, 0.85);
  headGroup.add(muzzle);

  const nose = new THREE.Mesh(new THREE.OctahedronGeometry(0.055, 0), pinkMat);
  nose.position.set(0.48, -0.08, 0);
  headGroup.add(nose);

  // ears
  const ears = [];
  for (const side of [-1, 1]) {
    const ear = new THREE.Group();
    ear.position.set(-0.02, 0.33, side * 0.2);
    ear.rotation.z = -0.16;
    ear.rotation.x = side * 0.22;
    const outer = new THREE.Mesh(new THREE.ConeGeometry(0.17, 0.36, 5), fur);
    outer.position.y = 0.12;
    ear.add(outer);
    const inner = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.25, 5), neon);
    inner.position.set(0.02, 0.11, 0);
    inner.scale.set(0.9, 0.9, 0.7);
    ear.add(inner);
    headGroup.add(ear);
    ears.push(ear);
  }

  // eyes
  const eyes = [];
  for (const side of [-1, 1]) {
    const eye = new THREE.Group();
    eye.position.set(0.31, 0.08, side * 0.155);
    const ball = new THREE.Mesh(new THREE.SphereGeometry(0.078, 12, 10), cyanMat);
    ball.scale.set(0.55, 1.05, 0.9);
    eye.add(ball);
    const glint = new THREE.Mesh(new THREE.SphereGeometry(0.026, 8, 6), new THREE.MeshBasicMaterial({ color: 0xffffff }));
    glint.position.set(0.05, 0.025, 0.02);
    eye.add(glint);
    headGroup.add(eye);
    eyes.push(eye);
  }

  // whiskers
  for (const side of [-1, 1]) {
    for (let i = 0; i < 2; i++) {
      const w = new THREE.Mesh(new THREE.CylinderGeometry(0.007, 0.004, 0.44, 4), cyanMat);
      w.position.set(0.5, -0.11 + i * 0.07, side * 0.12);
      w.rotation.z = Math.PI / 2 + (i === 0 ? 0.18 : -0.14);
      w.rotation.x = side * (0.35 + i * 0.12);
      headGroup.add(w);
    }
  }

  // collar + gem
  const collar = new THREE.Mesh(new THREE.TorusGeometry(0.33, 0.045, 8, 22), neon);
  collar.position.set(0.27, 1.26, 0);
  collar.rotation.y = Math.PI / 2;
  rig.add(collar);
  const gem = new THREE.Mesh(new THREE.OctahedronGeometry(0.1, 0), cyanMat);
  gem.position.set(0.34, 1.13, 0);
  rig.add(gem);

  /* ---------- legs ---------- */
  const legs = [];
  const legDefs = [
    { x: 0.28, z: 0.2, front: true },
    { x: 0.28, z: -0.2, front: true },
    { x: -0.26, z: 0.2, front: false },
    { x: -0.26, z: -0.2, front: false },
  ];
  for (const def of legDefs) {
    const pivot = new THREE.Group();
    pivot.position.set(def.x, 0.86, def.z);
    const upper = new THREE.Mesh(new THREE.CapsuleGeometry(0.105, 0.4, 5, 10), fur);
    upper.position.y = -0.29;
    upper.castShadow = true;
    pivot.add(upper);
    const paw = new THREE.Mesh(new THREE.SphereGeometry(0.14, 12, 9), furLight);
    paw.position.set(0.045, -0.6, 0);
    paw.scale.set(1.3, 0.72, 1);
    pivot.add(paw);
    const toe = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 6), neon);
    toe.position.set(0.16, -0.63, 0);
    toe.scale.set(1, 0.7, 1.3);
    pivot.add(toe);
    rig.add(pivot);
    legs.push({ pivot, front: def.front, side: Math.sign(def.z) });
  }

  /* ---------- tail ---------- */
  const tailBase = new THREE.Vector3(-0.52, 1.16, 0);
  const tail = [];
  const tailCount = 9;
  for (let i = 0; i < tailCount; i++) {
    const r = 0.125 * (1 - i / (tailCount + 2)) + 0.045;
    const seg = new THREE.Mesh(new THREE.SphereGeometry(r, 10, 8), i % 3 === 2 ? neon : fur);
    rig.add(seg);
    tail.push(seg);
  }
  const tailTip = new THREE.Mesh(new THREE.OctahedronGeometry(0.11, 0), cyanMat);
  rig.add(tailTip);

  /* ---------- aura ---------- */
  const auraTex = makeGlowTexture(128, 0.9);
  const auraMat = new THREE.SpriteMaterial({
    map: auraTex,
    color: 0xb44cff,
    transparent: true,
    opacity: 0,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const aura = new THREE.Sprite(auraMat);
  aura.scale.set(4.2, 4.2, 1);
  aura.position.set(0.1, 1.1, 0);
  rig.add(aura);

  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.62, 24),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.4, depthWrite: false })
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.02;
  shadow.scale.set(1.15, 0.7, 1);
  root.add(shadow);

  const state = {
    time: 0,
    phase: 0,
    blink: 0,
    blinkTimer: 2,
    invuln: 0,
    nova: 0,
    visTimer: 0,
  };

  function animate(dt, info) {
    const { speed = 0, grounded = true, vy = 0, mode = 'run' } = info;
    state.time += dt;
    state.phase += dt * (grounded ? 7.5 + speed * 0.5 : 3);

    // body bob & lean
    const runBob = grounded ? Math.abs(Math.sin(state.phase * 1.05)) * 0.055 : 0;
    const breathe = Math.sin(state.time * 1.7) * 0.012;
    rig.position.y = runBob + breathe + (mode === 'idle' ? Math.sin(state.time * 1.4) * 0.02 : 0);
    rig.rotation.z = THREE.MathUtils.lerp(rig.rotation.z, grounded ? -0.035 - Math.min(speed, 18) * 0.002 : -0.12, dt * 8);
    rig.rotation.x = Math.sin(state.phase * 0.5) * 0.02;

    // legs
    for (let i = 0; i < legs.length; i++) {
      const leg = legs[i];
      const off = i % 2 === 0 ? 0 : Math.PI;
      let target;
      if (grounded) {
        target = Math.sin(state.phase + off + (leg.front ? 0 : Math.PI)) * 0.8;
        if (mode === 'idle') target *= 0.12;
      } else {
        target = leg.front ? -0.95 : 0.75;
      }
      leg.pivot.rotation.z = THREE.MathUtils.lerp(leg.pivot.rotation.z, target, dt * 14);
      leg.pivot.rotation.x = leg.side * 0.06;
    }

    // head
    const headBob = grounded ? Math.sin(state.phase * 2) * 0.022 : 0;
    headGroup.position.y = 1.6 + headBob;
    headGroup.rotation.z = THREE.MathUtils.lerp(headGroup.rotation.z, grounded ? 0.05 : 0.2, dt * 6);
    headGroup.rotation.y = Math.sin(state.time * 0.9) * 0.05;

    // ears twitch
    for (let i = 0; i < ears.length; i++) {
      const twitch = Math.max(0, Math.sin(state.time * 1.3 + i * 2.1) - 0.96) * 2.2;
      ears[i].rotation.x = (i === 0 ? -1 : 1) * (0.22 + twitch * 0.4);
    }

    // blink
    state.blinkTimer -= dt;
    if (state.blinkTimer <= 0) {
      state.blinkTimer = 2.4 + Math.random() * 3.2;
      state.blink = 1;
    }
    state.blink = Math.max(0, state.blink - dt * 7);
    const eyeScale = 1 - state.blink * 0.88;
    for (const eye of eyes) eye.scale.y = Math.max(0.1, eyeScale);

    // tail
    for (let i = 0; i < tail.length; i++) {
      const t = i / (tail.length - 1);
      const wave = Math.sin(state.time * 2.4 - i * 0.52) * (0.05 + t * 0.06);
      const lift = grounded ? 0.12 : 0.26;
      tail[i].position.set(
        tailBase.x - t * 0.86 + Math.sin(state.time * 1.2 + i * 0.4) * 0.02,
        tailBase.y + t * (0.5 + lift) + wave - t * t * 0.12,
        Math.sin(state.time * 1.8 - i * 0.45) * (0.04 + t * 0.12)
      );
    }
    const last = tail[tail.length - 1];
    tailTip.position.set(last.position.x - 0.1, last.position.y + 0.06, last.position.z);

    // invulnerability blink
    if (state.invuln > 0) {
      state.invuln -= dt;
      state.visTimer += dt;
      rig.visible = Math.floor(state.visTimer * 14) % 2 === 0;
    } else {
      rig.visible = true;
      state.visTimer = 0;
    }

    // nova aura
    auraMat.opacity = THREE.MathUtils.lerp(auraMat.opacity, state.nova, dt * 5);
    aura.scale.setScalar(4.2 + Math.sin(state.time * 9) * 0.2 + state.nova * 1.8);
    gem.rotation.y += dt * 2.5;
    gem.scale.setScalar(1 + Math.sin(state.time * 4) * 0.12);
  }

  return {
    group: root,
    parts: { rig, bodyGroup, headGroup, legs, tail, tailTip, aura, shadow, ears, eyes, gem, mats },
    animate,
    setInvulnerable(seconds) { state.invuln = seconds; },
    setNova(v) { state.nova = v; },
    reset() {
      state.invuln = 0;
      state.nova = 0;
      state.phase = 0;
      rig.visible = true;
      auraMat.opacity = 0;
    },
  };
}

export function makeGlowTexture(size = 128, power = 0.9) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.18, `rgba(255,255,255,${0.85 * power})`);
  g.addColorStop(0.42, `rgba(255,255,255,${0.3 * power})`);
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

import * as THREE from 'three';
import { makeGlowTexture } from './cat.js';

const rand = (a, b) => a + Math.random() * (b - a);
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

export class World {
  constructor(scene, onEvent = () => {}) {
    this.scene = scene;
    this.onEvent = onEvent;
    this.platforms = [];
    this.obstacles = [];
    this.pickups = [];
    this.islands = [];
    this.bursts = [];
    this.rings = [];
    this.genX = 0;
    this.time = 0;
    this.supernovaTimer = 8;
    this.eventPulse = 0;
    this.cleanupTimer = 0;
    this.flashCount = 0;

    this._buildAssets();
    this._buildBackground();
    this._buildDust();
    this.reset();
  }

  /* ================= shared assets ================= */
  _buildAssets() {
    this.glowTex = makeGlowTexture(128, 1);
    this.sparkTex = makeGlowTexture(64, 0.85);

    this.geo = {
      box: new THREE.BoxGeometry(1, 1, 1),
      coin: new THREE.CylinderGeometry(0.42, 0.42, 0.1, 22),
      coinRim: new THREE.TorusGeometry(0.42, 0.055, 6, 24),
      crystal: new THREE.OctahedronGeometry(0.5, 0),
      flash: new THREE.IcosahedronGeometry(0.34, 1),
      spike: new THREE.ConeGeometry(0.58, 1.45, 4),
      orb: new THREE.IcosahedronGeometry(0.56, 1),
      ring: new THREE.TorusGeometry(0.78, 0.045, 6, 28),
      rock: new THREE.DodecahedronGeometry(1, 0),
      isleRing: new THREE.TorusGeometry(1.6, 0.05, 5, 28),
      shock: new THREE.RingGeometry(0.86, 1, 56),
    };

    this.mat = {
      dark: new THREE.MeshStandardMaterial({ color: 0x161028, roughness: 0.72, metalness: 0.55 }),
      slabSide: new THREE.MeshStandardMaterial({ color: 0x0d081a, roughness: 0.9, metalness: 0.3 }),
      cyan: new THREE.MeshStandardMaterial({ color: 0x0b2a30, emissive: 0x43f6ff, emissiveIntensity: 2.4, roughness: 0.3 }),
      purple: new THREE.MeshStandardMaterial({ color: 0x1c0a33, emissive: 0xb44cff, emissiveIntensity: 2.2, roughness: 0.3 }),
      pink: new THREE.MeshStandardMaterial({ color: 0x2a0a1a, emissive: 0xff4fa3, emissiveIntensity: 1.7, roughness: 0.35 }),
      coin: new THREE.MeshStandardMaterial({ color: 0x5a3a08, emissive: 0xffb320, emissiveIntensity: 1.5, roughness: 0.25, metalness: 0.8 }),
      coinRim: new THREE.MeshStandardMaterial({ color: 0x2a1a04, emissive: 0xffd166, emissiveIntensity: 2.0, roughness: 0.2, metalness: 0.9 }),
      crystal: new THREE.MeshStandardMaterial({ color: 0x083a42, emissive: 0x43f6ff, emissiveIntensity: 1.7, roughness: 0.1, metalness: 0.3, transparent: true, opacity: 0.94 }),
      flash: new THREE.MeshStandardMaterial({ color: 0x2a0a4a, emissive: 0xd070ff, emissiveIntensity: 2.8, roughness: 0.15, metalness: 0.2 }),
      rock: new THREE.MeshStandardMaterial({ color: 0x120a22, roughness: 0.95, metalness: 0.2, emissive: 0x2a0a4a, emissiveIntensity: 0.35 }),
      star: new THREE.PointsMaterial({ color: 0xc7a6ff, size: 0.5, transparent: true, opacity: 0.75, depthWrite: false, blending: THREE.AdditiveBlending, map: this.glowTex, sizeAttenuation: true }),
      dust: new THREE.PointsMaterial({ color: 0xb44cff, size: 0.16, transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending, map: this.glowTex, sizeAttenuation: true }),
    };

    this.spriteMat = {
      coin: new THREE.SpriteMaterial({ map: this.glowTex, color: 0xffc247, transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending, depthWrite: false }),
      crystal: new THREE.SpriteMaterial({ map: this.glowTex, color: 0x43f6ff, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false }),
      flash: new THREE.SpriteMaterial({ map: this.glowTex, color: 0xd070ff, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }),
    };

    this.spikeTipMat = new THREE.MeshBasicMaterial({ color: 0xff4fa3 });
  }

  /* ================= background ================= */
  _buildBackground() {
    const s = this.scene;

    s.fog = new THREE.FogExp2(0x0a0218, 0.0072);
    s.background = new THREE.Color(0x070111);

    const hemi = new THREE.HemisphereLight(0x9a6cff, 0x08020f, 1.15);
    s.add(hemi);
    const key = new THREE.DirectionalLight(0xbfe8ff, 2.0);
    key.position.set(6, 12, 8);
    s.add(key);
    const rim = new THREE.DirectionalLight(0xb44cff, 1.6);
    rim.position.set(-8, 5, -6);
    s.add(rim);
    this.catLight = new THREE.PointLight(0xb44cff, 34, 26, 2);
    this.catLight.position.set(0, 4, 5);
    s.add(this.catLight);

    // gradient backdrop
    const canvas = document.createElement('canvas');
    canvas.width = 1024;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');
    const g = ctx.createLinearGradient(0, 0, 0, 512);
    g.addColorStop(0, '#05010d');
    g.addColorStop(0.45, '#0e0322');
    g.addColorStop(0.78, '#1c0738');
    g.addColorStop(1, '#0a0218');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 1024, 512);
    const glow = ctx.createRadialGradient(730, 130, 0, 730, 130, 300);
    glow.addColorStop(0, 'rgba(196, 107, 255, 0.55)');
    glow.addColorStop(0.3, 'rgba(150, 60, 255, 0.22)');
    glow.addColorStop(1, 'rgba(90, 20, 160, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, 1024, 512);
    const neb = ctx.createRadialGradient(280, 250, 0, 280, 250, 380);
    neb.addColorStop(0, 'rgba(30, 120, 180, 0.18)');
    neb.addColorStop(1, 'rgba(20, 60, 120, 0)');
    ctx.fillStyle = neb;
    ctx.fillRect(0, 0, 1024, 512);
    const bgTex = new THREE.CanvasTexture(canvas);
    bgTex.colorSpace = THREE.SRGBColorSpace;
    const bgMat = new THREE.MeshBasicMaterial({ map: bgTex, depthWrite: false, fog: false });
    this.backdrop = new THREE.Mesh(new THREE.PlaneGeometry(320, 160), bgMat);
    this.backdrop.position.set(0, 34, -150);
    s.add(this.backdrop);

    // stars
    const starGeo = new THREE.BufferGeometry();
    const starPos = new Float32Array(340 * 3);
    for (let i = 0; i < 340; i++) {
      starPos[i * 3] = rand(-120, 120);
      starPos[i * 3 + 1] = rand(-6, 70);
      starPos[i * 3 + 2] = rand(-130, -25);
    }
    starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
    this.stars = new THREE.Points(starGeo, this.mat.star);
    s.add(this.stars);

    // supernova
    const sn = new THREE.Group();
    sn.position.set(18, 21, -92);
    this.supernova = sn;
    s.add(sn);

    this.snCore = new THREE.Mesh(
      new THREE.SphereGeometry(2.1, 24, 18),
      new THREE.MeshBasicMaterial({ color: 0xffe9ff })
    );
    sn.add(this.snCore);

    this.snHalo = new THREE.Mesh(
      new THREE.SphereGeometry(2.9, 24, 18),
      new THREE.MeshBasicMaterial({ color: 0xc56bff, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    sn.add(this.snHalo);

    const snGlow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.glowTex, color: 0xa64cff, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    snGlow.scale.set(34, 34, 1);
    sn.add(snGlow);
    this.snGlow = snGlow;

    for (let i = 0; i < 2; i++) {
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(4.6 + i * 1.5, 0.1, 6, 64),
        new THREE.MeshBasicMaterial({ color: i ? 0x43f6ff : 0xd9a6ff, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false })
      );
      ring.rotation.x = rand(0.6, 1.2);
      ring.rotation.y = rand(-0.4, 0.4);
      sn.add(ring);
      if (i === 0) this.snRing = ring;
      else this.snRing2 = ring;
    }

    const sparkGeo = new THREE.BufferGeometry();
    const sp = new Float32Array(70 * 3);
    for (let i = 0; i < 70; i++) {
      const r = rand(2.6, 7.2);
      const a = rand(0, Math.PI * 2);
      sp[i * 3] = Math.cos(a) * r;
      sp[i * 3 + 1] = Math.sin(a) * r * 0.8;
      sp[i * 3 + 2] = rand(-1.5, 1.5);
    }
    sparkGeo.setAttribute('position', new THREE.BufferAttribute(sp, 3));
    this.snSparks = new THREE.Points(sparkGeo, new THREE.PointsMaterial({
      color: 0xe0b6ff, size: 0.5, transparent: true, opacity: 0.85,
      blending: THREE.AdditiveBlending, depthWrite: false, map: this.glowTex,
    }));
    sn.add(this.snSparks);

    // shockwave pool
    for (let i = 0; i < 8; i++) {
      const m = new THREE.Mesh(this.geo.shock, new THREE.MeshBasicMaterial({
        color: 0xd070ff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
        depthWrite: false, side: THREE.DoubleSide,
      }));
      m.visible = false;
      m.renderOrder = 5;
      s.add(m);
