function updateCamera(dt, instant=false) {
  const aspect = innerWidth/innerHeight;
  const targetW = aspect > 1.05 ? 23.5 : 15;
  const d = clamp((targetW/2)/(Math.tan(fovRad)*aspect), 13, 55);
  const desiredX = (state==='title') ? 9 : G.catX + 2.3;
  camX = lerp(camX, desiredX, instant?1:1-Math.exp(-dt*6));
