Now append input handlers, update loop, resize, boot.

Potential issue in resumeGame: `last` is defined later (let last = performance.now()); in module scope hoisted with TDZ? `let last` declared later but resumeGame called after initialization, fine. Better use a variable defined. I'll define `let last = performance.now()` near bottom before loop; resumeGame references it at runtime after initialization. Fine.

Now the update function:

```js
function update(dt) {
  G.time += dt;
  if (G.state === 'playing') {
    G.elapsed += dt;
    G.speed = Math.min(MAX_SPEED, BASE_SPEED + G.elapsed * 0.115);
    const boost = G.novaActive > 0 ? 1.16 : 1;
    const speed = G.speed * boost;

    G.catX += speed * dt;

    // coyote
    if (G.grounded) G.coyote = 0.12; else G.coyote = Math.max(0, G.coyote - dt);

    // vertical physics
    if (!G.grounded) {
      G.vy += GRAVITY * dt;
      G.catY += G.vy * dt;
    }

    const plat = world.platformAt(G.catX);
    if (plat && G.catY <= 0) {
      if (!G.grounded && G.vy < -2) {
        audio.land();
        world.burst(G.catX, 0.1, 0x9a6cff, 6, 0.35);
      }
      G.catY = 0; G.vy = 0; G.grounded = true; G.jumps = 0;
    } else if (!plat) {
      if (G.grounded) { G.grounded = false; G.vy = Math.min(G.vy, 0); G.coyote = 0.1; }
    }

    if (G.catY < -4.2) fallIntoAbyss();

    // pickups
    const got = world.collectNear(G.catX, G.catY + 1.05, 0.5);
    if (got.length) {
      let gained = 0;
      const kinds = new Set();
      for (const p of got) {
        if (p.kind === 'coin') { G.coins++; gained += 10; novaGain(1.6); }
        else if (p.kind === 'crystal') { G.crystals++; gained += 60; novaGain(7); }
        else { G.flashes++; gained += 120; novaGain(13); }
        kinds.add(p.kind);
      }
      G.combo = Math.min(9, G.combo + Math.min(got.length, 3));
      G.bestCombo = Math.max(G.bestCombo, G.combo);
      G.comboTimer = 2.5;
      addScore(gained * G.combo);
      if (kinds.has('flash')) audio.flash();
      else if (kinds.has('crystal')) audio.crystal();
      else audio.coin();
      updateHud();
    }

    // combo timer
    if (G.comboTimer > 0) {
      G.comboTimer -= dt;
      if (G.comboTimer <= 0) G.combo = 1;
    }

    // obstacles
    G.invuln = Math.max(0, G.invuln - dt);
    if (G.invuln <= 0) {
      const hit = world.hitObstacle({ x0: G.catX - 0.36, x1: G.catX + 0.36, y0: G.catY + 0.12, y1: G.catY + 1.9 });
      if (hit) damage('hit');
    }

    // nova state
    if (G.novaActive > 0) {
      G.novaActive = Math.max(0, G.novaActive - dt);
      cat.setNova(1);
    } else cat.setNova(0);

    // distance score
    G.score += speed * dt * 0.9;

    // camera focus
    G.camX = lerp(G.camX, G.catX, 1 - Math.exp(-dt * 7));
  } else {
    G.camX = lerp(G.camX, G.state === 'title' ? START_X : G.catX, 1 - Math.exp(-dt * 4));
  }

  // effects shake decay
  G.shake = Math.max(0, G.shake - dt * 1.7);

  // world update (always animate)
  world.update(dt, G.catX, G.camX);

  // cat position & animation
  cat.group.position.x = G.catX;
  cat.group.position.y = G.catY;
  cat.group.position.z = 0;
  const runSpeed = G.state === 'playing' ? G.speed : 0;
  cat.animate(dt, {
    speed: runSpeed,
    grounded: G.grounded,
    vy: G.vy,
    mode: G.state === 'playing' ? 'run' : 'idle',
  });

  // camera
  updateCamera(dt);

  // banner
  if (bannerTimer > 0) {
    bannerTimer -= dt;
    if (bannerTimer <= 0) $('banner').classList.remove('show');
  }

  // HUD periodic
  updateHud();
  if (G.state === 'playing') updateHud(); // fine
}
```

Issue: `world.update` calls generateAhead(catX+150) during title too, extending world infinitely while title (catX 8) but capped by 150. Fine.

fallIntoAbyss may be called when catY < -4.2 repeatedly? After respawn catY=0. Good. But if target platform doesn't exist? It picks nearest ahead. Note world.platforms may not include next platform if generated only 150 ahead — yes includes.

When respawning to target.x0+3, cat could be inside an obstacle; invuln 2.1 protects. Good.

Grounded logic: when standing at y=0 and platform exists, fine. When running off edge: catY=0, no platform → grounded=false, vy=0, falls next frames. Good.

But when jumping from platform and still over platform with catY>0, no landing until y<=0. Fine.

If cat jumps and platform ends, catY>0; when crossing gap and y>0 no platform; lands on next if y<=0 and platform exists. Good.

Coyote: set each frame grounded. doJump checks coyote>0. On leaving platform, we set coyote=0.1. But in update, `if (G.grounded) G.coyote=0.12; else G.coyote -= dt` — at start of frame when grounded set, then if leaving sets 0.1. Fine.

Camera update:

```js
function updateCamera(dt) {
  const aspect = window.innerWidth / window.innerHeight;
  const targetW = aspect > 1.08 ? 23.5 : 15.5;
  const fovRad = THREE.MathUtils.degToRad(camera.fov / 2);
  const d = clamp((targetW / 2) / (Math.tan(fovRad) * aspect), 13, 58);
  const shakeX = (Math.random() - 0.5) * G.shake;
  const shakeY = (Math.random() - 0.5) * G.shake * 0.7;
  const targetX = G.camX + 3.1 + shakeX;
